function base64UrlDecode(e){for(e=e.replace(/-/g,"+").replace(/_/g,"/");e.length%4;)e+="=";const t=atob(e);try{return decodeURIComponent(t.split("").map(e=>"%"+("00"+e.charCodeAt(0).toString(16)).slice(-2)).join(""))}catch(e){return t}}function formatTs(e){const t=new Date(1e3*e);return`${t.toISOString()} (${t.toString()})`}async function decodeJwt(){const e=document.getElementById("jwtInput").value.trim(),t=document.getElementById("jwtResult"),n=document.getElementById("verifyResult");if(!e)return t.innerHTML="",void(n.style.display="none");const o=e.split(".");if(o.length<2)return t.innerHTML=`<div class="callout error" style="margin-top:20px;">That doesn't look like a JWT — expected three dot-separated segments (header.payload.signature), found ${o.length}.</div>`,void(n.style.display="none");let a,r;try{a=JSON.parse(base64UrlDecode(o[0]))}catch(e){return t.innerHTML='<div class="callout error" style="margin-top:20px;">Couldn\'t parse the header segment as JSON. Check the token was copied in full.</div>',void(n.style.display="none")}try{r=JSON.parse(base64UrlDecode(o[1]))}catch(e){return t.innerHTML='<div class="callout error" style="margin-top:20px;">Couldn\'t parse the payload segment as JSON. Check the token was copied in full.</div>',void(n.style.display="none")}const i=Math.floor(Date.now()/1e3);let l="";if(r.exp){const e=r.exp<i;l+=`<div class="callout ${e?"error":"ok"}">exp: ${formatTs(r.exp)} — ${e?"expired":"valid"} ${e?"("+Math.round((i-r.exp)/60)+" min ago)":"("+Math.round((r.exp-i)/60)+" min from now)"}</div>`}if(r.nbf){const e=r.nbf>i;l+=`<div class="callout ${e?"warn":"ok"}">nbf: ${formatTs(r.nbf)} — ${e?"not valid yet":"already active"}</div>`}r.iat&&(l+=`<div class="callout ok">iat (issued at): ${formatTs(r.iat)}</div>`),t.innerHTML=`\n    <div class="tool-grid" style="margin-top:20px;">\n      <div class="config-block">\n        <div class="tab">header <button class="copy-btn" onclick="copyJson('jwtHeaderOut', this)">copy</button></div>\n        <div class="output-block"><pre id="jwtHeaderOut">${escapeHtml(JSON.stringify(a,null,2))}</pre></div>\n      </div>\n      <div class="config-block">\n        <div class="tab">payload <button class="copy-btn" onclick="copyJson('jwtPayloadOut', this)">copy</button></div>\n        <div class="output-block"><pre id="jwtPayloadOut">${escapeHtml(JSON.stringify(r,null,2))}</pre></div>\n      </div>\n    </div>\n    ${l?'<div style="margin-top:6px;">'+l+"</div>":""}\n  `;const s=document.getElementById("jwtSecret").value;if(s){if(n.style.display="block","HS256"!==a.alg)return n.className="callout warn",void(n.innerHTML=`Verification only supported for HS256 algorithm. Current token uses: <strong>${escapeHtml(a.alg)}</strong>`);try{await verifyHS256(o[0],o[1],o[2],s)?(n.className="callout ok",n.innerHTML="✔ Signature Verified (HS256)"):(n.className="callout error",n.innerHTML="✖ Invalid Signature")}catch(e){n.className="callout error",n.innerHTML=`Verification error: ${escapeHtml(e.message)}`}}else n.style.display="none"}async function verifyHS256(e,t,n,o){const a=new TextEncoder,r=await crypto.subtle.importKey("raw",a.encode(o),{name:"HMAC",hash:"SHA-256"},!1,["verify"]);let i=n.replace(/-/g,"+").replace(/_/g,"/");for(;i.length%4;)i+="=";const l=new Uint8Array(atob(i).split("").map(e=>e.charCodeAt(0))),s=a.encode(`${e}.${t}`);return await crypto.subtle.verify("HMAC",r,l,s)}function escapeHtml(e){const t=document.createElement("div");return t.textContent=e,t.innerHTML}function copyJson(e,t){navigator.clipboard.writeText(document.getElementById(e).textContent),flashCopied(t)}